import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { RotatingChevron } from "@/registry/erbium/ui/stateful-icon";
import { Separator } from "@/registry/erbium/ui/separator";

const Accordion = ({ className, ...props }: AccordionPrimitive.Root.Props) => (
  <AccordionPrimitive.Root
    data-slot="accordion"
    className={cn("flex w-full flex-col", className)}
    {...props}
  />
);

const AccordionItem = ({ className, children, ...props }: AccordionPrimitive.Item.Props) => (
  <AccordionPrimitive.Item
    data-slot="accordion-item"
    className={cn("group/accordion-item", className)}
    {...props}
  >
    {children}
    <Separator data-slot="accordion-item-separator" className="group-last/accordion-item:hidden" />
  </AccordionPrimitive.Item>
);

const AccordionTrigger = ({ className, children, ...props }: AccordionPrimitive.Trigger.Props) => (
  <AccordionPrimitive.Header className="flex">
    <AccordionPrimitive.Trigger
      data-slot="accordion-trigger"
      className={cn(
        "group group/accordion-trigger relative flex flex-1 items-start justify-between rounded-lg border border-transparent min-h-control control-adaptive py-related text-start text-control-sm font-medium transition-colors outline-none hover:underline data-panel-open:rounded-b-none group-has-[[data-slot=accordion-content]:not([hidden])]/accordion-item:rounded-b-none focus-visible:border-ring focus-visible:after:border-ring **:data-[slot=accordion-trigger-icon]:ms-auto **:data-[slot=accordion-trigger-icon]:size-4 **:data-[slot=accordion-trigger-icon]:text-muted-foreground data-disabled:pointer-events-none data-disabled:opacity-50",
        className,
      )}
      {...props}
    >
      {children}
      <RotatingChevron data-slot="accordion-trigger-icon" className="pointer-events-none" />
    </AccordionPrimitive.Trigger>
  </AccordionPrimitive.Header>
);

const AccordionContent = ({ className, children, ...props }: AccordionPrimitive.Panel.Props) => (
  <AccordionPrimitive.Panel
    data-slot="accordion-content"
    className="h-(--accordion-panel-height) overflow-hidden text-caption transition-[height] duration-200 ease-in-out data-ending-style:h-0 data-starting-style:h-0 motion-reduce:transition-none"
    {...props}
  >
    <div
      className={cn(
        "pt-2.5 pb-2.5 [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground [&_p:not(:last-child)]:mb-4",
        className,
      )}
    >
      {children}
    </div>
  </AccordionPrimitive.Panel>
);

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

import * as React from "react";
import { Icon } from "@/registry/erbium/ui/icon";
import { cn } from "@/registry/erbium/lib/erbium-utils";

type AlertVariant = "default" | "info" | "success" | "warning" | "error";

const alertVariants: Record<AlertVariant, { className: string; icon: React.ReactNode }> = {
  default: {
    className: "surface-panel text-card-foreground",
    icon: <Icon name="info" aria-hidden="true" />,
  },
  error: {
    className: "surface-tint-error-soft text-error-soft-foreground",
    icon: <Icon name="octagon-x" className="text-error" aria-hidden="true" />,
  },
  info: {
    className: "surface-tint-info-soft text-info-soft-foreground",
    icon: <Icon name="info" className="text-info" aria-hidden="true" />,
  },
  success: {
    className: "surface-tint-success-soft text-success-soft-foreground",
    icon: <Icon name="circle-check" className="text-success" aria-hidden="true" />,
  },
  warning: {
    className: "surface-tint-warning-soft text-warning-soft-foreground",
    icon: <Icon name="triangle-alert" className="text-warning" aria-hidden="true" />,
  },
};

const Alert = ({
  className,
  variant = "default",
  children,
  ...props
}: React.ComponentProps<"div"> & { variant?: AlertVariant }) => (
  <div
    data-slot="alert"
    role="alert"
    className={cn(
      "group/alert relative grid w-full grid-cols-[auto_1fr] gap-x-2 gap-y-0.5 rounded-lg border px-2.5 py-2 text-start text-caption has-data-[slot=alert-action]:pe-18 [&>svg]:row-span-2 [&>svg]:size-4 [&>svg]:translate-y-0.5",
      alertVariants[variant].className,
      className,
    )}
    {...props}
  >
    {alertVariants[variant].icon}
    {children}
  </div>
);

const AlertTitle = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-title"
    className={cn(
      "col-start-2 text-control [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground",
      className,
    )}
    {...props}
  />
);

const AlertDescription = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-description"
    className={cn(
      "col-start-2 text-caption text-balance text-muted-foreground md:text-pretty [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground [&_p:not(:last-child)]:mb-4",
      className,
    )}
    {...props}
  />
);

const AlertAction = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div data-slot="alert-action" className={cn("absolute top-2 inset-e-2", className)} {...props} />
);

export { Alert, AlertTitle, AlertDescription, AlertAction };

export type { AlertVariant };

import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "@base-ui/react/alert-dialog";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Button } from "@/registry/erbium/ui/button";

const AlertDialog = ({ ...props }: AlertDialogPrimitive.Root.Props) => (
  <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />
);

const AlertDialogTrigger = ({ ...props }: AlertDialogPrimitive.Trigger.Props) => (
  <AlertDialogPrimitive.Trigger data-slot="alert-dialog-trigger" {...props} />
);

const AlertDialogPortal = ({ ...props }: AlertDialogPrimitive.Portal.Props) => (
  <AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />
);

const AlertDialogOverlay = ({ className, ...props }: AlertDialogPrimitive.Backdrop.Props) => (
  <AlertDialogPrimitive.Backdrop
    data-slot="alert-dialog-overlay"
    className={cn(
      "fixed inset-0 isolate z-50 bg-overlay-backdrop duration-100 supports-backdrop-filter:backdrop-blur-(--overlay-backdrop-blur,2px) data-open:animate-in data-open:fade-in-0 data-closed:animate-out data-closed:fade-out-0",
      className,
    )}
    {...props}
  />
);

const AlertDialogViewport = ({ className, ...props }: AlertDialogPrimitive.Viewport.Props) => (
  <AlertDialogPrimitive.Viewport
    data-slot="alert-dialog-viewport"
    className={cn(
      "fixed inset-0 z-50 grid grid-rows-[1fr_auto_3fr] justify-items-center p-4",
      className,
    )}
    {...props}
  />
);

const AlertDialogContent = ({
  className,
  size = "default",
  ...props
}: AlertDialogPrimitive.Popup.Props & {
  size?: "default" | "sm";
}) => (
  <AlertDialogPortal>
    <AlertDialogOverlay />
    <AlertDialogViewport>
      <AlertDialogPrimitive.Popup
        data-slot="alert-dialog-content"
        data-size={size}
        className={cn(
          "group/alert-dialog-content relative row-start-2 grid max-h-[calc(100dvh-2rem)] w-full gap-group overflow-hidden rounded-xl surface-modal separator-inset p-panel text-popover-foreground duration-100 outline-none data-[size=default]:max-w-xs data-[size=sm]:max-w-xs data-[size=default]:sm:max-w-sm data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
          className,
        )}
        {...props}
      />
    </AlertDialogViewport>
  </AlertDialogPortal>
);

const AlertDialogHeader = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-dialog-header"
    className={cn(
      "grid grid-rows-[auto_1fr] place-items-center gap-1.5 text-center has-data-[slot=alert-dialog-media]:grid-rows-[auto_auto_1fr] has-data-[slot=alert-dialog-media]:gap-x-4 sm:group-data-[size=default]/alert-dialog-content:place-items-start sm:group-data-[size=default]/alert-dialog-content:text-start sm:group-data-[size=default]/alert-dialog-content:has-data-[slot=alert-dialog-media]:grid-rows-[auto_1fr]",
      className,
    )}
    {...props}
  />
);

const AlertDialogFooter = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-dialog-footer"
    className={cn(
      "-mx-(--panel-padding) -mb-(--panel-padding) flex flex-col-reverse gap-related surface-footer p-panel group-data-[size=sm]/alert-dialog-content:grid group-data-[size=sm]/alert-dialog-content:grid-cols-2 sm:flex-row sm:justify-end",
      className,
    )}
    {...props}
  />
);

const AlertDialogMedia = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-dialog-media"
    className={cn(
      "mb-2 inline-flex size-10 items-center justify-center rounded-md bg-muted sm:group-data-[size=default]/alert-dialog-content:row-span-2 *:[svg:not([class*='size-'])]:size-6",
      className,
    )}
    {...props}
  />
);

const AlertDialogTitle = ({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Title>) => (
  <AlertDialogPrimitive.Title
    data-slot="alert-dialog-title"
    className={cn(
      "text-subtitle sm:group-data-[size=default]/alert-dialog-content:group-has-data-[slot=alert-dialog-media]/alert-dialog-content:col-start-2",
      className,
    )}
    {...props}
  />
);

const AlertDialogDescription = ({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Description>) => (
  <AlertDialogPrimitive.Description
    data-slot="alert-dialog-description"
    className={cn(
      "text-caption text-muted-foreground *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
      className,
    )}
    {...props}
  />
);

const AlertDialogAction = ({ className, ...props }: React.ComponentProps<typeof Button>) => (
  <Button data-slot="alert-dialog-action" className={cn(className)} {...props} />
);

const AlertDialogCancel = ({
  className,
  variant = "outline",
  size = "default",
  ...props
}: AlertDialogPrimitive.Close.Props &
  Pick<React.ComponentProps<typeof Button>, "variant" | "size">) => (
  <AlertDialogPrimitive.Close
    data-slot="alert-dialog-cancel"
    className={cn(className)}
    render={<Button variant={variant} size={size} />}
    {...props}
  />
);

export {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogOverlay,
  AlertDialogPortal,
  AlertDialogTitle,
  AlertDialogTrigger,
};

import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { CSSVariableStyle } from "@/registry/erbium/lib/erbium-utils";

const AspectRatio = ({
  ratio,
  className,
  style,
  ...props
}: React.ComponentProps<"div"> & { ratio: number }) => {
  // Merged rather than replaced, so a consumer `style` keeps the ratio.
  const ratioStyle: CSSVariableStyle = { "--ratio": ratio, ...style };

  return (
    <div
      data-slot="aspect-ratio"
      className={cn("relative aspect-(--ratio)", className)}
      {...props}
      style={ratioStyle}
    />
  );
};

export { AspectRatio };

import * as React from "react";
import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cva } from "class-variance-authority";
import type { VariantProps } from "class-variance-authority";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Button } from "@/registry/erbium/ui/button";
import { ScrollArea } from "@/registry/erbium/ui/scroll-area";

const attachmentVariants = cva(
  "group/attachment relative flex w-fit max-w-full min-w-0 shrink-0 flex-wrap rounded-xl border bg-card text-card-foreground transition-colors focus-within:border-ring has-[>a,>button]:hover:bg-muted-hover data-[state=error]:border-error/30 data-[state=idle]:border-dashed",
  {
    variants: {
      orientation: {
        horizontal: "min-w-40 items-center",
        vertical: "w-24 flex-col has-data-[slot=attachment-content]:w-30",
      },
      size: {
        default:
          "gap-related text-caption has-data-[slot=attachment-content]:px-2.5 has-data-[slot=attachment-content]:py-2 has-data-[slot=attachment-media]:p-2",
        sm: "gap-2.5 text-metadata has-data-[slot=attachment-content]:px-2 has-data-[slot=attachment-content]:py-1.5 has-data-[slot=attachment-media]:p-1.5",
        xs: "gap-1.5 rounded-lg text-metadata has-data-[slot=attachment-content]:px-1.5 has-data-[slot=attachment-content]:py-1 has-data-[slot=attachment-media]:p-1",
      },
    },
  },
);

const Attachment = ({
  className,
  state = "done",
  size = "default",
  orientation = "horizontal",
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof attachmentVariants> & {
    state?: "idle" | "uploading" | "processing" | "error" | "done";
  }) => (
  <div
    data-slot="attachment"
    data-state={state}
    data-size={size}
    data-orientation={orientation}
    className={cn(attachmentVariants({ orientation, size }), className)}
    {...props}
  />
);

const attachmentMediaVariants = cva(
  "relative flex aspect-square w-10 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-muted text-foreground group-data-[orientation=vertical]/attachment:w-full group-data-[size=sm]/attachment:w-8 group-data-[size=xs]/attachment:w-7 group-data-[size=xs]/attachment:rounded-md group-data-[state=error]/attachment:bg-error/10 group-data-[state=error]/attachment:text-error group-data-[orientation=vertical]/attachment:*:data-[slot=spinner]:size-6! [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 group-data-[orientation=vertical]/attachment:[&_svg:not([class*='size-'])]:size-6 group-data-[size=xs]/attachment:[&_svg:not([class*='size-'])]:size-3.5",
  {
    defaultVariants: {
      variant: "icon",
    },
    variants: {
      variant: {
        icon: "",
        image:
          "image-hairline opacity-60 group-data-[state=done]/attachment:opacity-100 group-data-[state=idle]/attachment:opacity-100 *:[img]:aspect-square *:[img]:w-full *:[img]:object-cover",
      },
    },
  },
);

const AttachmentMedia = ({
  className,
  variant = "icon",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof attachmentMediaVariants>) => (
  <div
    data-slot="attachment-media"
    data-variant={variant}
    className={cn(attachmentMediaVariants({ variant }), className)}
    {...props}
  />
);

const AttachmentContent = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="attachment-content"
    className={cn(
      "max-w-full min-w-0 flex-1 group-data-[orientation=vertical]/attachment:px-1",
      className,
    )}
    {...props}
  />
);

const AttachmentTitle = ({ className, ...props }: React.ComponentProps<"span">) => (
  <span
    data-slot="attachment-title"
    className={cn(
      "block max-w-full min-w-0 truncate font-medium group-data-[state=processing]/attachment:shimmer group-data-[state=uploading]/attachment:shimmer",
      className,
    )}
    {...props}
  />
);

const AttachmentDescription = ({ className, ...props }: React.ComponentProps<"span">) => (
  <span
    data-slot="attachment-description"
    className={cn(
      "mt-0.5 block min-w-0 truncate text-metadata text-muted-foreground group-data-[state=error]/attachment:text-error/80",
      "max-w-full",
      className,
    )}
    {...props}
  />
);

const AttachmentActions = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="attachment-actions"
    className={cn(
      "relative z-20 flex shrink-0 items-center group-data-[orientation=vertical]/attachment:absolute group-data-[orientation=vertical]/attachment:top-3 group-data-[orientation=vertical]/attachment:inset-e-3 group-data-[orientation=vertical]/attachment:gap-1",
      className,
    )}
    {...props}
  />
);

const AttachmentAction = ({
  className,
  variant,
  size = "icon-xs",
  ...props
}: React.ComponentProps<typeof Button>) => (
  <Button
    data-slot="attachment-action"
    variant={variant ?? "ghost"}
    size={size}
    className={cn(className)}
    {...props}
  />
);

const AttachmentTrigger = ({
  className,
  render,
  type,
  ...props
}: useRender.ComponentProps<"button">) =>
  useRender({
    defaultTagName: "button",
    props: mergeProps<"button">(
      {
        className: cn("absolute inset-0 z-10 outline-none", className),
        type: render ? type : (type ?? "button"),
      },
      props,
    ),
    render,
    state: {
      slot: "attachment-trigger",
    },
  });

const AttachmentGroup = ({ className, children, ...props }: React.ComponentProps<"div">) => (
  <ScrollArea
    className="min-w-0"
    fade="horizontal"
    scrollbar="none"
    viewportClassName="overflow-y-hidden!"
    viewportRender={
      <div
        data-slot="attachment-group"
        className={cn("snap-x snap-mandatory scroll-px-1 overscroll-x-contain", className)}
        {...props}
      />
    }
    contentClassName="flex min-w-full gap-3 py-1 *:data-[slot=attachment]:flex-none *:data-[slot=attachment]:snap-start"
  >
    {children}
  </ScrollArea>
);

export {
  Attachment,
  AttachmentGroup,
  AttachmentMedia,
  AttachmentContent,
  AttachmentTitle,
  AttachmentDescription,
  AttachmentActions,
  AttachmentAction,
  AttachmentTrigger,
};

import { Autocomplete as AutocompletePrimitive } from "@base-ui/react/autocomplete";
import { Input } from "@/registry/erbium/ui/input";
import { ScrollArea } from "@/registry/erbium/ui/scroll-area";
import { Separator } from "@/registry/erbium/ui/separator";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { cva } from "class-variance-authority";
import { Icon } from "@/registry/erbium/ui/icon";
import { focusSearchInput } from "@/registry/erbium/lib/focus-search-input";

import type React from "react";

export const Autocomplete: typeof AutocompletePrimitive.Root = AutocompletePrimitive.Root;

/** Search within an inline surface; form fields use AutocompleteInput. */
export const AutocompleteSearchInput = ({
  className,
  placeholder = "Search…",
  ...props
}: AutocompletePrimitive.Input.Props) => (
  <div data-slot="autocomplete-search" className="shrink-0">
    <div
      className="flex search-input-row items-center"
      onPointerDown={(event) => {
        focusSearchInput(event.currentTarget, event);
      }}
    >
      <Icon
        name="search-01"
        aria-hidden="true"
        className="size-control-icon shrink-0 text-muted-foreground"
      />
      <AutocompletePrimitive.Input
        data-slot="autocomplete-search-input"
        aria-label="Search"
        placeholder={placeholder}
        className={cn(
          "min-h-0 min-w-0 flex-1 bg-transparent py-0 text-field outline-hidden placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50",
          className,
        )}
        {...props}
      />
    </div>
    <Separator variant="full" />
  </div>
);

const autocompleteInputVariants = cva("", {
  variants: {
    size: {
      default:
        "has-[+[data-slot=autocomplete-trigger],+[data-slot=autocomplete-clear]]:*:data-[slot=autocomplete-input]:pe-7",
      lg: "has-[+[data-slot=autocomplete-trigger],+[data-slot=autocomplete-clear]]:*:data-[slot=autocomplete-input]:pe-7",
      sm: "has-[+[data-slot=autocomplete-trigger],+[data-slot=autocomplete-clear]]:*:data-[slot=autocomplete-input]:pe-6.5",
    },
    startAddon: {
      false: "",
      true: "data-[size=sm]:*:data-[slot=autocomplete-input]:ps-[calc(--spacing(7.5)-1px)] *:data-[slot=autocomplete-input]:ps-[calc(--spacing(8.5)-1px)] sm:data-[size=sm]:*:data-[slot=autocomplete-input]:ps-[calc(--spacing(7)-1px)] sm:*:data-[slot=autocomplete-input]:ps-[calc(--spacing(8)-1px)]",
    },
  },
});

const autocompleteFieldVariants = cva("", {
  variants: {
    size: {
      default: "",
      lg: "control-size-lg text-field",
      sm: "control-size-sm text-field",
    },
  },
});

const autocompleteActionVariants = cva(
  "absolute top-1/2 inline-flex size-control shrink-0 -translate-y-1/2 cursor-pointer items-center justify-center rounded-md border border-transparent opacity-80 outline-none transition-colors pointer-coarse:after:absolute pointer-coarse:after:min-h-11 pointer-coarse:after:min-w-11 hover:opacity-100 has-[+[data-slot=autocomplete-clear]]:hidden sm:size-control-sm [&_svg:not([class*='size-'])]:size-4.5 sm:[&_svg:not([class*='size-'])]:size-control-icon [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      size: {
        default: "inset-e-0.5",
        lg: "inset-e-0.5",
        sm: "inset-e-0",
      },
    },
  },
);

export const AutocompleteTrigger = ({
  className,
  children,
  ...props
}: AutocompletePrimitive.Trigger.Props): React.ReactElement => (
  <AutocompletePrimitive.Trigger className={className} data-slot="autocomplete-trigger" {...props}>
    {children}
  </AutocompletePrimitive.Trigger>
);

export const AutocompleteClear = ({
  className,
  ...props
}: AutocompletePrimitive.Clear.Props): React.ReactElement => (
  <AutocompletePrimitive.Clear
    className={cn(
      "absolute inset-e-0.5 top-1/2 inline-flex size-control shrink-0 -translate-y-1/2 cursor-pointer items-center justify-center rounded-md border border-transparent opacity-80 outline-none transition-[color,background-color,box-shadow,opacity] pointer-coarse:after:absolute pointer-coarse:after:min-h-11 pointer-coarse:after:min-w-11 hover:opacity-100 sm:size-control-sm [&_svg:not([class*='size-'])]:size-4.5 sm:[&_svg:not([class*='size-'])]:size-control-icon [&_svg]:pointer-events-none [&_svg]:shrink-0",
      className,
    )}
    data-slot="autocomplete-clear"
    {...props}
  >
    <Icon name="x" />
  </AutocompletePrimitive.Clear>
);

export const AutocompleteInput = ({
  className,
  showTrigger = false,
  showClear = false,
  startAddon,
  size,
  triggerProps,
  clearProps,
  ...props
}: Omit<AutocompletePrimitive.Input.Props, "size"> & {
  showTrigger?: boolean;
  showClear?: boolean;
  startAddon?: React.ReactNode;
  size?: "sm" | "default" | "lg" | number;
  ref?: React.Ref<HTMLInputElement>;
  triggerProps?: AutocompletePrimitive.Trigger.Props;
  clearProps?: AutocompletePrimitive.Clear.Props;
}): React.ReactElement => {
  const sizeValue = size ?? "default";
  const visualSize = typeof sizeValue === "number" ? "default" : sizeValue;

  return (
    <AutocompletePrimitive.InputGroup
      className="relative not-has-[>*.w-full]:w-fit w-full text-foreground has-disabled:opacity-64"
      data-slot="autocomplete-input-group"
    >
      {startAddon && (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-y-0 inset-s-px z-10 flex items-center ps-[calc(--spacing(3)-1px)] opacity-80 has-[+[data-size=sm]]:ps-[calc(--spacing(2.5)-1px)] [&_svg:not([class*='size-'])]:size-4.5 sm:[&_svg:not([class*='size-'])]:size-control-icon [&_svg]:-mx-0.5"
          data-slot="autocomplete-start-addon"
        >
          {startAddon}
        </div>
      )}
      <AutocompletePrimitive.Input
        className={cn(
          autocompleteInputVariants({ className, size: visualSize, startAddon: !!startAddon }),
        )}
        data-slot="autocomplete-input"
        render={<Input className={cn(autocompleteFieldVariants({ size: visualSize }))} />}
