const badgeStatusIcons = {
  error: "octagon-x",
  "ghost-error": "octagon-x",
  "ghost-info": "info",
  "ghost-success": "circle-check",
  "ghost-warning": "triangle-alert",
  info: "info",
  success: "circle-check",
  warning: "triangle-alert",
} as const satisfies Record<string, IconName>;

const isStatusVariant = (variant: unknown): variant is keyof typeof badgeStatusIcons =>
  typeof variant === "string" && variant in badgeStatusIcons;

type BadgeProps = useRender.ComponentProps<"span"> & { loading?: boolean } & (
    | { variant: keyof typeof badgeStatusIcons; statusIcon: true }
    | (VariantProps<typeof badgeVariants> & { statusIcon?: false })
  );

const Badge = ({
  children,
  className,
  loading = false,
  variant = "default",
  statusIcon = false,
  render,
  "aria-busy": ariaBusy,
  ...props
}: BadgeProps) => {
  const icon = statusIcon && isStatusVariant(variant) ? badgeStatusIcons[variant] : null;

  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(
      {
        "aria-busy": loading || ariaBusy,
        children: (
          <>
            {loading && <Spinner aria-hidden data-icon="inline-start" size="xs" />}
            {!loading && icon && <Icon name={icon} data-icon="inline-start" aria-hidden="true" />}
            {children}
          </>
        ),
        className: cn(badgeVariants({ variant }), className),
      },
      props,
    ),
    render,
    state: {
      loading,
      slot: "badge",
      variant,
    },
  });
};

export { Badge, badgeVariants };

