  CodePanelCopyButton,
  CodePanelHeader,
  CodePanelTitle,
  codePanelFocusRing,
  codePanelSurface,
} from "@/registry/erbium/blocks/code-panel";
import type { CopyButtonProps } from "@/registry/erbium/blocks/copy-button";

type CodeToken = TokensResult["tokens"][number][number];

/** Highlighted output from `highlightCode`, for code tokenized ahead of render. */
type CodeBlockTokens = Pick<TokensResult, "tokens" | "rootStyle">;

const CodeBlockToken = ({ token }: { token: CodeToken }) => {
  const htmlStyle = "htmlStyle" in token ? token.htmlStyle : undefined;

  const tokenStyle: CSSVariableStyle = {
    "--shiki-dark": htmlStyle?.["--shiki-dark"],
    "--shiki-light": htmlStyle?.["--shiki-light"],
  };

  return (
    <span
      style={tokenStyle}
      data-italic={htmlStyle?.["font-style"] === "italic" ? "" : undefined}
      data-bold={htmlStyle?.["font-weight"] === "bold" ? "" : undefined}
      className="text-(--shiki-light,inherit) dark:text-(--shiki-dark,inherit) data-italic:italic data-bold:font-bold"
    >
      {token.content}
    </span>
  );
};

interface CodeBlockItem {
  value: string;
  label: string;
  code: string;
  language?: string;
  tokens?: CodeBlockTokens;
  disabled?: boolean;
}

type CodeBlockSource =
  | { code: string; language?: string; tokens?: CodeBlockTokens; items?: never }
  | { items: readonly CodeBlockItem[]; code?: never; language?: never; tokens?: never };

type CodeBlockProps = Omit<
  TabsPrimitive.Root.Props,
  "value" | "defaultValue" | "onValueChange" | "orientation" | "dir"
> &
  CodeBlockSource & {
    dir?: never;
    value?: string;
    defaultValue?: string;
    onValueChange?: (value: string, details: TabsPrimitive.Root.ChangeEventDetails) => void;
    surface?: "code" | "command";
    lineNumbers?: boolean;
    wrap?: boolean;
    title?: string;
  };

interface CodeBlockContextValue {
  items: readonly CodeBlockItem[];
  active: CodeBlockItem | undefined;
  surface: "code" | "command";
  lineNumbers: boolean;
  wrap: boolean;
}

const CodeBlockContext = createContext<CodeBlockContextValue | null>(null);

const useCodeBlock = () => {
  const context = use(CodeBlockContext);

  if (!context) {
    throw new Error("Code block parts must be inside CodeBlock.");
  }

  return context;
};

const CodeBlockHeader = ({ className, ...props }: ComponentProps<typeof CodePanelHeader>) => (
  <CodePanelHeader
    {...props}
    data-slot="code-block-header"
    className={cn("flex-nowrap pe-12 group-data-[surface=command]/code-block:min-h-9", className)}
  />
);

const CodeBlockTitle = ({ className, ...props }: ComponentProps<typeof CodePanelTitle>) => (
  <CodePanelTitle {...props} data-slot="code-block-title" className={cn("truncate", className)} />
);

const CodeBlockActions = ({ className, ...props }: ComponentProps<"div">) => (
  <div
    {...props}
    data-slot="code-block-actions"
    className={cn(
      "absolute end-2 top-2 z-10 flex items-center gap-1 rounded-md bg-surface-panel",
      className,
    )}
  />
);

const CodeBlockLanguage = ({ children, ...props }: ComponentProps<typeof CodeBlockTitle>) => {
  const { active } = useCodeBlock();

  return <CodeBlockTitle {...props}>{children ?? active?.language ?? "text"}</CodeBlockTitle>;
};

const CodeBlockIcon = ({
  value,
  className,
  ...props
}: Omit<ComponentProps<typeof Icon>, "name"> & { value?: string }) => {
  const { active, items, surface } = useCodeBlock();
  const item = value === undefined ? active : items.find((entry) => entry.value === value);

  return (
    <Icon
      {...props}
      className={cn("size-4.5", className)}
      name={codeLanguageIcon(item?.language ?? (surface === "command" ? "shell" : undefined))}
      data-slot="code-block-icon"
    />
  );
};

const CodeBlockTab = (props: ComponentProps<typeof TabsTrigger>) => <TabsTrigger {...props} />;

const CodeBlockTabs = ({
  children,
  className,
  "aria-label": label = "Code examples",
  ...props
}: ComponentProps<typeof TabsList>) => {
  const { items } = useCodeBlock();

  return (
    <TabsList
      {...props}
      aria-label={label}
      className={cn("h-7 min-w-0 max-w-full overflow-x-auto", className)}
    >
      {children ??
        items.map((item) => (
          <CodeBlockTab key={item.value} value={item.value} disabled={item.disabled}>
            <CodeBlockIcon value={item.value} />
            {item.label}
          </CodeBlockTab>
        ))}
    </TabsList>
  );
};

const CodeBlockCopyButton = ({
  value,
  ...props
}: Omit<CopyButtonProps, "value"> & { value?: string }) => {
  const { active, surface } = useCodeBlock();

  return (
    <CodePanelCopyButton
      value={value ?? active?.code ?? ""}
      aria-label={surface === "command" ? "Copy command" : "Copy code"}
      disabled={!active}
      {...props}
    />
  );
};

type CodeBlockContentProps = Omit<
  ComponentProps<"pre">,
  "children" | "dangerouslySetInnerHTML" | "dir"
>;

const CodeBlockContent = ({ className, style, ...props }: CodeBlockContentProps) => {
  const { active, lineNumbers, wrap, surface } = useCodeBlock();
  const code = active?.code ?? "";
  const language = active?.language ?? "text";
  const tokens = active?.tokens;

  const [highlighted, setHighlighted] = useState<{
    code: string;
    language: string;
    result: TokensResult;
  }>();

  useEffect(() => {
    let current = true;

    const highlight = async () => {
      try {
        const result = await highlightCode(code, language);

        if (current) {
          setHighlighted({ code, language, result });
        }
      } catch {
        // Source remains readable as plain text when highlighting is unavailable.
      }
    };

    // Provided tokens render on the server and skip the client highlighter.
    if (tokens === undefined && !["text", "plaintext", "plain", "txt", ""].includes(language)) {
      void highlight();
    }

    return () => {
      current = false;
    };
  }, [code, language, tokens]);

  const result =
    tokens ??
    (highlighted?.code === code && highlighted.language === language
      ? highlighted.result
      : undefined);

  const rows: TokensResult["tokens"] =
    result?.tokens ?? code.split(/\r\n|\n|\r/u).map((content) => [{ content, offset: 0 }]);

  // Shiki reports `false` when the theme sets no root style.
  const rootStyle = result?.rootStyle;
  const declarations = rootStyle === undefined || rootStyle === false ? [] : rootStyle.split(";");

  const themeColor = (name: string) => {
    const declaration = declarations.find((entry) => entry.startsWith(`${name}:`));

    return declaration?.slice(name.length + 1);
  };

  const blockStyle: CSSVariableStyle = {
    "--shiki-dark": themeColor("--shiki-dark"),
    "--shiki-light": themeColor("--shiki-light"),
    ...style,
  };

  return (
    <pre
      {...props}
      data-slot="code-block-content"
      data-language={language}
      dir="ltr"
      // Long code scrolls inside a fixed height; keyboard users need a tab stop to scroll it
      // (WCAG 2.1.1, axe scrollable-region-focusable). The rule only knows interactive roles.
      // oxlint-disable-next-line jsx-a11y/no-noninteractive-tabindex
      tabIndex={0}
      style={blockStyle}
      className={cn(
        "m-0 max-h-120 overflow-auto p-panel text-code-block [tab-size:2] text-(--shiki-light,inherit) dark:text-(--shiki-dark,inherit)",
        codePanelFocusRing,
        wrap ? "whitespace-pre-wrap break-words" : "whitespace-pre",
        surface === "command" && "px-3 py-3",
        "group-has-[[data-slot=code-block-actions]]/code-block:pe-12",
        className,
      )}
    >
      <code>
        {rows.map((row, index) => (
          <span key={index} data-slot="code-block-line">
            {lineNumbers && (
              <span
                aria-hidden="true"
                className="me-5 inline-block min-w-6 select-none text-end text-muted-foreground/60"
              >
                {index + 1}
              </span>
            )}
            {row.map((token, tokenIndex) => (
              <CodeBlockToken key={tokenIndex} token={token} />
            ))}
            {index < rows.length - 1 ? "\n" : null}
          </span>
        ))}
      </code>
    </pre>
  );
};

const CodeBlockPanel = ({
  value,
  ...props
}: Omit<TabsPrimitive.Panel.Props, "children"> & { value: string }) => {
  const context = useCodeBlock();

  const panelContext = useMemo(
    () => ({ ...context, active: context.items.find((entry) => entry.value === value) }),
    [context, value],
  );

  return (
    <TabsPrimitive.Panel {...props} value={value} data-slot="code-block-panel">
      <CodeBlockContext value={panelContext}>
        <CodeBlockContent />
      </CodeBlockContext>
    </TabsPrimitive.Panel>
  );
};

const CodeBlock = ({
  code,
  language,
  tokens,
  items: providedItems,
  value,
  defaultValue,
  onValueChange,
  surface = "code",
  lineNumbers = false,
  wrap = false,
  title,
  children,
  className,
  ...props
}: CodeBlockProps) => {
  const items = useMemo(
    () =>
      providedItems ?? [
        { code: code ?? "", label: title ?? language ?? "Code", language, tokens, value: "code" },
      ],
    [providedItems, code, language, title, tokens],
  );

  const [selection, setSelection] = useState(defaultValue);
  const requested = value ?? selection;

  const enabled = items.filter((item) => item.disabled !== true);
  const active = enabled.find((item) => item.value === requested) ?? enabled.at(0);

  const context = useMemo(
    () => ({ active, items, lineNumbers, surface, wrap }),
    [active, items, lineNumbers, surface, wrap],
  );

  const hasTabs = providedItems !== undefined && items.length > 0;
  const hasTitle = title !== undefined && title !== "";

  return (
    <DirectionProvider direction="ltr">
      <CodeBlockContext value={context}>
        <TabsPrimitive.Root
          {...props}
          dir="ltr"
          data-slot="code-block"
          data-surface={surface}
          className={cn("group/code-block relative", codePanelSurface, className)}
          value={active?.value ?? null}
          onValueChange={(next, details) => {
            // Tabs report any value; only an item's value selects code.
            const item = items.find((entry) => entry.value === next);

            if (!item) {
              return;
            }

            onValueChange?.(item.value, details);

            if (!details.isCanceled && value === undefined) {
              setSelection(item.value);
            }
          }}
        >
          {children ?? (
            <>
              {hasTabs || hasTitle ? (
                <CodeBlockHeader>
                  {hasTabs ? (
                    <CodeBlockTabs />
                  ) : (
                    <CodeBlockTitle>
                      <CodeBlockIcon />
                      <span className="truncate">{title}</span>
                    </CodeBlockTitle>
                  )}
                </CodeBlockHeader>
              ) : null}
              <CodeBlockActions>
                <CodeBlockCopyButton />
              </CodeBlockActions>
              {providedItems ? (
                items.map((item) => <CodeBlockPanel key={item.value} value={item.value} />)
              ) : (
                <CodeBlockContent />
              )}
            </>
          )}
        </TabsPrimitive.Root>
      </CodeBlockContext>
    </DirectionProvider>
  );
};

export {
  CodeBlock,
  CodeBlockHeader,
  CodeBlockTitle,
  CodeBlockActions,
  CodeBlockLanguage,
  CodeBlockIcon,
  CodeBlockTabs,
  CodeBlockTab,
  CodeBlockPanel,
  CodeBlockContent,
  CodeBlockCopyButton,
};

export type { CodeBlockProps, CodeBlockItem, CodeBlockContentProps, CodeBlockTokens };

import type { HighlighterCore, TokensResult } from "shiki/core";

const languages = {
  css: async () => await import("shiki/langs/css.mjs"),
  html: async () => await import("shiki/langs/html.mjs"),
  js: async () => await import("shiki/langs/javascript.mjs"),
  json: async () => await import("shiki/langs/json.mjs"),
  jsx: async () => await import("shiki/langs/jsx.mjs"),
  markdown: async () => await import("shiki/langs/markdown.mjs"),
  python: async () => await import("shiki/langs/python.mjs"),
  shell: async () => await import("shiki/langs/shellscript.mjs"),
  sql: async () => await import("shiki/langs/sql.mjs"),
  ts: async () => await import("shiki/langs/typescript.mjs"),
  tsx: async () => await import("shiki/langs/tsx.mjs"),
  yaml: async () => await import("shiki/langs/yaml.mjs"),
};

const aliases: Record<string, string> = {
  bash: "shell",
  javascript: "js",
  md: "markdown",
  py: "python",
  sh: "shell",
  shellscript: "shell",
  typescript: "ts",
  yml: "yaml",
};

type Language = keyof typeof languages;

const names: Record<Language, string> = {
  css: "css",
  html: "html",
  js: "javascript",
  json: "json",
  jsx: "jsx",
  markdown: "markdown",
  python: "python",
  shell: "shellscript",
  sql: "sql",
  ts: "typescript",
  tsx: "tsx",
  yaml: "yaml",
};

let highlighter: Promise<HighlighterCore> | undefined;
const languageRequests = new Map<Language, Promise<void>>();

export const normalizeCodeLanguage = (language: string) => {
  const name = language.trim().toLowerCase();

  return aliases[name] ?? name;
};

const getHighlighter = async () => {
  highlighter ??= Promise.all([
    import("shiki/core"),
    import("shiki/engine/javascript"),
    import("shiki/themes/vitesse-light.mjs"),
    import("shiki/themes/vitesse-dark.mjs"),
  ])
    .then(
      async ([core, engine, light, dark]) =>
        await core.createHighlighterCore({
          engine: engine.createJavaScriptRegexEngine(),
          langs: [],
          themes: [light.default, dark.default],
        }),
    )
    .catch((error: unknown) => {
      highlighter = undefined;
      throw error;
    });

  return await highlighter;
};

// One runtime and one in-flight grammar load per language, shared by every block.
const tokenizeCode = async (code: string, language: string) => {
  const instance = await getHighlighter();
  const normalized = normalizeCodeLanguage(language);
  let lang = "text";

  if (Object.hasOwn(languages, normalized)) {
    const key = normalized as Language;
    lang = names[key];

    if (!instance.getLoadedLanguages().includes(lang)) {
      let request = languageRequests.get(key);

      if (!request) {
        request = languages[key]()
          .then(async (module) => {
            await instance.loadLanguage(module.default);
          })
          .finally(() => languageRequests.delete(key));
        languageRequests.set(key, request);
      }

      await request;
    }
  }

  return instance.codeToTokens(code, {
    defaultColor: false,
    lang,
    themes: { dark: "vitesse-dark", light: "vitesse-light" },
  });
};

const cache = new Map<string, { result: TokensResult; size: number }>();
const requests = new Map<string, Promise<TokensResult>>();
let cacheSize = 0;
const maxCacheSize = 2 * 1024 * 1024;

export const highlightCode = async (code: string, language: string): Promise<TokensResult> => {
  const normalized = normalizeCodeLanguage(language);
  const key = `${normalized}\u0000${code}`;
  const cached = cache.get(key);

  if (cached) {
    cache.delete(key);
    cache.set(key, cached);

    return cached.result;
  }

  const pending = requests.get(key);

  if (pending) {
    return await pending;
  }

  const request = tokenizeCode(code, normalized)
    .then((result) => {
      const size = code.length * 2 + JSON.stringify(result.tokens).length * 2;

      if (size <= maxCacheSize) {
        cache.set(key, { result, size });
        cacheSize += size;

        while (cache.size > 100 || cacheSize > maxCacheSize) {
          const oldest = cache.keys().next().value;

          if (oldest === undefined) {
            break;
          }

          cacheSize -= cache.get(oldest)?.size ?? 0;
          cache.delete(oldest);
        }
      }

      return result;
    })
    .finally(() => requests.delete(key));

  requests.set(key, request);

  return await request;
};

import type { ComponentProps, ReactNode } from "react";
import { DirectionProvider } from "@/registry/erbium/ui/direction";
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/registry/erbium/ui/empty";
import { Separator } from "@/registry/erbium/ui/separator";
import { Spinner } from "@/registry/erbium/ui/spinner";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { CopyButton } from "@/registry/erbium/blocks/copy-button";
import type { CopyButtonProps } from "@/registry/erbium/blocks/copy-button";

// Shared chrome for blocks that present source code: the surface, header, title,
// actions, and the scrollable body. Code is direction-neutral, so every panel
// stays LTR even on RTL pages.
const codePanelSurface = "min-w-0 w-full overflow-hidden rounded-xl surface-panel text-foreground";
const codePanelHeader = "flex min-h-10 items-center justify-between gap-related px-3 py-1.5";

const codePanelTitle =
  "inline-flex min-w-0 items-center gap-related text-metadata font-medium text-muted-foreground";

const codePanelFocusRing =
  "outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring";

type CodePanelProps = Omit<ComponentProps<"div">, "dir" | "dangerouslySetInnerHTML">;

const CodePanel = ({ className, ...props }: CodePanelProps) => (
  <DirectionProvider direction="ltr">
    <div data-slot="code-panel" {...props} dir="ltr" className={cn(codePanelSurface, className)} />
  </DirectionProvider>
);

const CodePanelHeader = ({ className, ...props }: ComponentProps<"div">) => (
  <>
    <div
      data-slot="code-panel-header"
      {...props}
      className={cn(codePanelHeader, "flex-wrap", className)}
    />
    <Separator variant="full" />
  </>
);

const CodePanelTitle = ({ className, ...props }: ComponentProps<"span">) => (
  <span data-slot="code-panel-title" {...props} className={cn(codePanelTitle, className)} />
);

const CodePanelActions = ({ className, ...props }: ComponentProps<"div">) => (
  <div
    data-slot="code-panel-actions"
    {...props}
    className={cn("flex shrink-0 items-center gap-related", className)}
  />
);

const CodePanelCopyButton = ({ children, ...props }: CopyButtonProps) => (
  <CopyButton
    variant="ghost"
    size={children === undefined || children === null ? "icon-xs" : "xs"}
    {...props}
  >
    {children}
  </CopyButton>
);

type CodePanelContentProps = Omit<ComponentProps<"section">, "dir" | "dangerouslySetInnerHTML"> & {
  /** Shown above the rendered code until the renderer has produced output. */
  loading?: boolean;
  /** Replaces the body when there is nothing to render. */
  empty?: ReactNode;
};

const CodePanelContent = ({
  loading,
  empty,
  children,
  className,
  ...props
}: CodePanelContentProps) => {
  const showEmpty = empty !== undefined && empty !== null && empty !== false;

  return (
    <section
      aria-busy={loading === true ? true : undefined}
      data-slot="code-panel-content"
      {...props}
      dir="ltr"
      className={cn(
        "max-h-120 min-w-0 overflow-auto bg-surface-panel",
        codePanelFocusRing,
        className,
      )}
    >
      {showEmpty ? (
        empty
      ) : (
        <>
          {loading === true ? (
            <div className="flex min-h-32 items-center justify-center text-muted-foreground">
              <Spinner size="lg" />
            </div>
          ) : null}
          {children}
        </>
      )}
    </section>
  );
};

const CodePanelEmpty = ({ title, description }: { title: ReactNode; description?: ReactNode }) => (
  <Empty className="rounded-none border-0 p-panel sm:p-panel">
    <EmptyHeader>
      <EmptyTitle>{title}</EmptyTitle>
      {description !== undefined && description !== null ? (
        <EmptyDescription>{description}</EmptyDescription>
      ) : null}
