const initializedRoots = new WeakSet<ShadowRoot>();

// Pierre 1.5 renders expansion controls as div[role=button]. Supply names,
// focusability, and native button keyboard behavior after each render.
const enhanceDiffAccessibility = (host: HTMLElement) => {
  const root = host.shadowRoot;

  if (!root) {
    return;
  }

  for (const button of root.querySelectorAll<HTMLElement>("[data-expand-button]")) {
    button.tabIndex = 0;
    button.setAttribute(
      "aria-label",
      Object.hasOwn(button.dataset, "expandAllButton")
        ? "Expand all unchanged lines"
        : Object.hasOwn(button.dataset, "expandUp")
          ? "Expand unchanged lines above"
          : Object.hasOwn(button.dataset, "expandDown")
            ? "Expand unchanged lines below"
            : "Expand unchanged lines",
    );
  }

  if (initializedRoots.has(root)) {
    return;
  }

  initializedRoots.add(root);
  root.addEventListener("keydown", (event) => {
    if (!(event instanceof KeyboardEvent)) {
      return;
    }

    const { target } = event;

    if (!(target instanceof HTMLElement) || !target.matches("[data-expand-button]")) {
      return;
    }

    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }

    event.preventDefault();
    target.click();
  });
};

export { enhanceDiffAccessibility };

import { iconDefinitions } from "@erbium/icons";
import type { IconName } from "@erbium/icons";
import { spriteSheets } from "@erbium/icons/sprite";

// Pierre draws its controls from a sprite inside the shadow root. Point the
// icons Erbium renders at the shared set so a diff matches the rest of the UI.
const replacements: Record<string, IconName> = {
  "diffs-icon-expand": "chevron-down",
  "diffs-icon-expand-all": "unfold-more",
  "diffs-icon-plus": "plus",
};

const markup = `<svg data-icon-sprite data-erbium-icons aria-hidden="true" width="0" height="0">${Object.values(
  replacements,
)
  .map((name) => {
    const match = new RegExp(
      `<symbol[^>]*\\sid="${iconDefinitions[name].id}"[\\s\\S]*?</symbol>`,
    ).exec(spriteSheets.ui);

    return match?.[0] ?? "";
  })
  .join("")}</svg>`;

const applyDiffIcons = (host: HTMLElement) => {
  const root = host.shadowRoot;

  if (!root) {
    return;
  }

  if (!root.querySelector("[data-erbium-icons]")) {
    const template = document.createElement("template");
    template.innerHTML = markup;
    root.prepend(template.content);
  }

  for (const use of root.querySelectorAll("use")) {
    const name = replacements[use.getAttribute("href")?.replace(/^#/, "") ?? ""];

    if (name) {
      use.setAttribute("href", `#${iconDefinitions[name].id}`);
    }
  }
};

export { applyDiffIcons };

