                    <span className="sr-only">Close</span>
                  </DrawerPrimitive.Close>
                )}
              </div>
            </DrawerPrimitive.Popup>
          </DrawerPrimitive.Viewport>
        </DrawerPortal>
      </KeyboardProvider>
    </DrawerPanelContext.Provider>
  );
};

