import { spriteSheets } from "@erbium/icons/sprite";

const byFileName: Record<string, IconName> = {
  ".gitattributes": "git",
  ".gitignore": "git",
  ".gitmodules": "git",
  ".npmrc": "npm-duo",
  "bun.lock": "bun",
