    className={cn("min-w-full", className)}
    {...props}
  />
);

const ScrollBar = ({
  className,
  orientation = "vertical",
  size = "thin",
  visibility = "always",
  thumbClassName,
  ...props
}: ScrollAreaPrimitive.Scrollbar.Props & {
  size?: ScrollBarSize;
  visibility?: ScrollBarVisibility;
  thumbClassName?: string;
}) => (
