    {...props}
  >
    <ScrollAreaPrimitive.Thumb
      data-slot="scroll-area-thumb"
      className={cn(scrollBarThumbVariants({ className: thumbClassName, orientation, size }))}
    />
  </ScrollAreaPrimitive.Scrollbar>
);

const ScrollArea = ({
  className,
  children,
  fade = "vertical",
  orientation = "vertical",
  scrollbar = "thin",
  scrollbarVisibility = "always",
  viewportClassName,
  viewportRole,
  viewportRender,
  contentClassName,
  scrollbarClassName,
  thumbClassName,
  ...props
}: ScrollAreaProps) => {
  const showScrollbar = scrollbar !== "none";

