/* Erbium effects. The text `shimmer` utility comes from `shadcn/tailwind.css`. */

/*
 * Skeleton sweep. The gradient is attached to the viewport (`fixed`), so every
 * skeleton on screen shares one band that travels across the page at the same
 * speed regardless of element size. The Skeleton component pins each animation
 * to the document timeline so late-mounting skeletons stay in phase.
 */
@theme inline {
  --animate-skeleton: skeleton var(--skeleton-duration, var(--shimmer-duration, 2s)) -1s infinite
    linear;

  @keyframes skeleton {
    to {
      background-position: -200% 0;
    }
  }
}

@utility skeleton {
  animation: var(--animate-skeleton);
  background-attachment: fixed;
  background-color: var(--color-skeleton);

  /* Highlight band eased with an ease-in-out curve (cubic-bezier(.42, 0, .58, 1)). */
  background-image: linear-gradient(
    calc(90deg + var(--shimmer-angle)),
    transparent 30%,
    color-mix(in oklab, var(--color-skeleton-highlight) 7.4%, transparent) 33.8%,
    color-mix(in oklab, var(--color-skeleton-highlight) 25.9%, transparent) 37%,
    color-mix(in oklab, var(--color-skeleton-highlight) 50%, transparent) 40%,
    color-mix(in oklab, var(--color-skeleton-highlight) 74.1%, transparent) 43%,
    color-mix(in oklab, var(--color-skeleton-highlight) 92.6%, transparent) 46.2%,
    var(--color-skeleton-highlight) 50%,
    color-mix(in oklab, var(--color-skeleton-highlight) 92.6%, transparent) 53.8%,
    color-mix(in oklab, var(--color-skeleton-highlight) 74.1%, transparent) 57%,
    color-mix(in oklab, var(--color-skeleton-highlight) 50%, transparent) 60%,
    color-mix(in oklab, var(--color-skeleton-highlight) 25.9%, transparent) 63%,
    color-mix(in oklab, var(--color-skeleton-highlight) 7.4%, transparent) 66.2%,
    transparent 70%
  );
  background-position: 0 0;
  background-repeat: repeat;
  background-size: 200% 100%;

  &:where([dir="rtl"], [dir="rtl"] *) {
    animation-direction: reverse;
  }

  @media (prefers-reduced-motion: reduce) {
    animation: none;
    background-image: none;
  }
}

