@import "./surfaces.css";
@import "./chart.css";
@import "./variants.css";
@import "./effects.css";
@import "./typeset.css";
@import "./base.css";
@import "./scrollbar.css";

@plugin "easing-gradients";

/* Only suppress transitions for the palette swap; normal interaction motion resumes afterward. */
html[data-theme-changing],
html[data-theme-changing] *,
html[data-theme-changing] *::before,
html[data-theme-changing] *::after {
  transition: none !important;
}

@utility animate-in {
  animation: var(--animate-in);
}

@utility animate-out {
  animation: var(--animate-out);
}

@utility animate-caret-blink {
  animation: caret-blink 1s step-end infinite;
}

@keyframes caret-blink {
  50% {
    opacity: 0;
  }
}

@utility rounded-avatar {
  @apply rounded-[35%];
}

@utility transition-sidebar-size {
  @apply transition-[width,height,padding];
}

@utility shadow-sidebar-outline {
  @apply shadow-[0_0_0_1px_var(--sidebar-border)];
}

@utility shadow-sidebar-outline-hover {
  @apply shadow-[0_0_0_1px_var(--sidebar-accent)];
}

@utility transition-field {
  @apply transition-[color,box-shadow];
}

@utility transition-button {
  @apply transition-[color,background-color,box-shadow];
}

@utility ring-control {
  @apply ring-[1.5px];
}

@utility rounded-button-xs {
  @apply rounded-[min(var(--radius-md),10px)];
}

@utility rounded-button-sm {
  @apply rounded-[min(var(--radius-md),12px)];
}

/* Native document, code, table and textarea scrollers share ScrollArea's palette. */
@theme {
  --spacing-scrollbar-track: 0.5rem;
  --spacing-scrollbar-thumb: 0.375rem;
  --spacing-scrollbar-track-default: 0.625rem;
  --spacing-scrollbar-thumb-default: 0.5rem;
}

@theme inline {
  --color-scrollbar-thumb: var(--scrollbar-thumb);
  --color-scrollbar-thumb-hover: var(--scrollbar-thumb-hover);
  --color-scrollbar-thumb-active: var(--scrollbar-thumb-active);
  --color-scrollbar-thumb-scrolling: var(--scrollbar-thumb-scrolling);
}

@layer base {
  * {
    --scrollbar-thumb: color-mix(in srgb, var(--muted-foreground) 35%, transparent);
    --scrollbar-thumb-hover: color-mix(in srgb, var(--muted-foreground) 55%, transparent);
    --scrollbar-thumb-active: color-mix(in srgb, var(--muted-foreground) 70%, transparent);
    --scrollbar-thumb-scrolling: color-mix(in srgb, var(--muted-foreground) 60%, transparent);

    scrollbar-color: var(--scrollbar-thumb) transparent;
    scrollbar-width: thin;
  }

  *::-webkit-scrollbar {
    width: var(--spacing-scrollbar-track);
    height: var(--spacing-scrollbar-track);
  }

  *::-webkit-scrollbar-track,
  *::-webkit-scrollbar-corner {
    background: transparent;
  }

  *::-webkit-scrollbar-thumb {
    border: 1px solid transparent;
    border-radius: 999px;
    background: var(--scrollbar-thumb);
    background-clip: padding-box;
  }

  *::-webkit-scrollbar-thumb:hover {
    background-color: var(--scrollbar-thumb-hover);
  }

  *::-webkit-scrollbar-thumb:active {
    background-color: var(--scrollbar-thumb-active);
  }

  @media (forced-colors: active) {
    * {
      scrollbar-color: auto;
    }
  }
}

@utility scrollbar-thin {
  scrollbar-width: thin;
}

@utility scrollbar-gutter-stable {
  scrollbar-gutter: stable;
}

@utility scrollbar-thumb-transparent {
  scrollbar-color: transparent transparent;

  &::-webkit-scrollbar-thumb {
    background: transparent;
  }
}

@utility scrollbar-track-transparent {
  &::-webkit-scrollbar-track {
    background: transparent;
  }
}

/* Mira density, coordinated with Erbium typography. All dimensions respect zoom. */

/* Public decisions. Component recipes own all other dimensions. These are
   deliberately outside @theme: heights must not become generic gap/padding knobs. */
@layer base {
  :root {
    --control-height-embedded: 1.25rem;
    --control-height-small: 1.5rem;
    --control-height: 1.75rem;
    --control-height-large: 2rem;
    --space-related: 0.5rem;
    --space-group: 1rem;
    --space-section: 1.5rem;
    --panel-padding: 1rem;
    --panel-padding-compact: 0.75rem;
  }
}

/* Minimum height plus padding lets scripts, text zoom, and touch fields grow. */
@utility control-size {
  min-height: max(var(--control-height), var(--control-target-floor, 0px));
  gap: 0.25rem;
  padding-block: 0.1875rem;
  padding-inline: 0.5rem;
}

@utility control-size-sm {
  min-height: max(var(--control-height-small), var(--control-target-floor, 0px));
  gap: 0.25rem;
  padding-block: 0.125rem;
  padding-inline: 0.5rem;
}

@utility control-size-xs {
  --control-target-floor: 0px;

  min-height: max(var(--control-height-embedded), var(--control-target-floor, 0px));
  gap: 0.25rem;
  padding-block: 0;
  padding-inline: 0.375rem;
}

@utility control-size-lg {
  min-height: max(var(--control-height-large), var(--control-target-floor, 0px));
  gap: 0.375rem;
  padding-block: 0.1875rem;
  padding-inline: 0.625rem;
}

@utility control-adaptive {
  @media (width < 48rem) {
    --control-target-floor: 2.25rem;

    min-width: 2.25rem;
    min-height: var(--control-target-floor);
  }

  @media (pointer: coarse) {
    --control-target-floor: 2.75rem;

    min-width: 2.75rem;
    min-height: var(--control-target-floor);
  }
}

@utility row-size {
  min-height: var(--control-height);
  gap: 0.25rem;
  padding-block: 0.25rem;
  padding-inline: 0.375rem;

  @media (pointer: coarse) {
    --control-target-floor: 2.75rem;

    min-height: var(--control-target-floor);
  }
}

@utility min-h-control-xs {
  min-height: max(var(--control-height-embedded), var(--control-target-floor, 0px));
}

@utility min-h-control-sm {
  min-height: max(var(--control-height-small), var(--control-target-floor, 0px));
}

@utility min-h-control {
  min-height: max(var(--control-height), var(--control-target-floor, 0px));
}

@utility min-h-control-lg {
  min-height: max(var(--control-height-large), var(--control-target-floor, 0px));
}

@utility min-h-control-touch {
  --control-target-floor: 2.75rem;

  min-height: var(--control-target-floor);
}

@utility min-h-badge {
  min-height: 1.25rem;
}

@utility min-w-control-sm {
  min-width: var(--control-height-small);
}

@utility min-w-control {
  min-width: var(--control-height);
}

@utility min-w-control-lg {
  min-width: var(--control-height-large);
}

@utility gap-control-gap {
  gap: 0.25rem;
}

@utility gap-related {
  gap: var(--space-related);
}

@utility gap-group {
  gap: var(--space-group);
}

@utility gap-section {
  gap: var(--space-section);
}

@utility p-panel {
  padding: var(--panel-padding);
}

@utility p-panel-sm {
  padding: var(--panel-padding-compact);
}

@utility px-related {
  padding-inline: var(--space-related);
}

@utility px-control-inset {
  padding-inline: 0.5rem;
}

@utility py-related {
  padding-block: var(--space-related);
}

@utility py-control-gap {
  padding-block: 0.25rem;
}

@utility h-row {
  height: var(--control-height);
}

@utility size-control-xs {
  width: var(--control-height-embedded);
  height: var(--control-height-embedded);
}

@utility size-control-sm {
  width: var(--control-height-small);
  height: var(--control-height-small);
}

@utility size-control {
  width: var(--control-height);
  height: var(--control-height);
}

@utility size-control-lg {
  width: var(--control-height-large);
  height: var(--control-height-large);
}

@utility size-control-icon {
  width: 0.875rem;
  height: 0.875rem;
}

@utility size-control-icon-sm {
  width: 0.75rem;
  height: 0.75rem;
}

@utility size-control-icon-lg {
  width: 1rem;
  height: 1rem;
}

@utility size-choice {
  width: 0.875rem;
  height: 0.875rem;
}

@utility px-panel {
  padding-inline: var(--panel-padding);
}

@utility py-panel {
  padding-block: var(--panel-padding);
}

@utility segmented-size {
  min-height: calc(max(var(--control-height), var(--control-target-floor, 0px)) - 0.375rem);
}

@utility control-embedded {
  --control-target-floor: 0px;

  min-width: 0;
}

@utility h-track {
  height: 0.25rem;
}

@utility w-track {
  width: 0.25rem;
}

@utility size-thumb {
  width: 0.75rem;
  height: 0.75rem;
}

/* Search headers separate editable text from the results below it. */
@utility search-input-row {
  & > input {
    padding-block: 0;
  }

  min-height: 2.5rem;
  gap: 0.5rem;
  padding-block: 0.5rem;
  padding-inline: 0.75rem;

  @media (width < 48rem), (pointer: coarse) {
    min-height: 3rem;
  }
}

/*
 * Surfaces: a lit, layered elevation system.
 *
 * Light falls from the top. Raised surfaces catch it on their top edge and
 * cast a short shadow below; pressed and selected controls sink into their
 * plane. An element takes one surface class for its role. Framed surfaces
 * own their border and forced-colors fallback. The class sets the face colour, the
 * perimeter, the catchlight, the drop shadows, and every interaction state:
 *
 *   surface-panel          cards, frames, table containers, alerts
 *   surface-control        buttons, triggers, toggles, keycaps, indicators
 *   surface-field          inputs, textareas, OTP slots, input groups
 *   surface-overlay        popovers, menus, select popups, toasts
 *   surface-modal          dialogs, sheets, drawers
 *   surface-footer         attached action area, with a carved top divider
 *   surface-flat           ghost and secondary controls: no elevation
 *   surface-frame          hairline-framed flat parts
 *   surface-well           recessed tracks; use sparingly
 *   surface-knob           switch, slider, and pad thumbs
 *   surface-fill-{color}   solid coloured controls (primary, error, ...)
 *   surface-tint-{color}   opaque soft coloured panels (soft alerts, badges)
 *   surface-tag-{color}    translucent coloured tags
 *   surface-ghost-{color}  flat controls whose states paint a colour
 *                          (ghost-error buttons and badges)
 *
 * States come from the element, never from extra classes:
 *   hover / press        links, buttons, comboboxes, and tabs (the
 *                        surface-interactive variant) get a tint overlay on
 *                        any surface; raised controls also sink
 *   engaged              aria-expanded, aria-pressed, data-state="on", and an
 *                        open popup tint a surface and sink a raised control
 *                        into its plane
 *   invalid              aria-invalid (on the element or its direct input)
 *                        turns a control or field perimeter error
 *   disabled             :disabled, data-disabled, aria-disabled, or a
 *                        disabled direct input flatten a control to its
 *                        hairline; a selected control keeps its tint
 * surface-flat owns the tint states. surface-control owns the sink, invalid,
 * and disabled states, and surface-field and surface-fill-* build on it, so
 * pressed beats engaged and disabled beats both in every raised role.
 *
 * Coloured faces derive their perimeter and catchlight from the face colour,
 * so any colour works in both themes:
 *   fill   solid faces are darker than either canvas; the catchlight is the
 *          face lifted toward white, sitting on the top edge of the rim
 *   tint   soft faces sit near the light canvas, where a whiter edge would
 *          vanish. Light mode keeps the tinted rim at half strength on the
 *          top edge instead. --surface-catchlight-lift picks between the two
 *          (0% lifted rim, 100% lifted face).
 *   ghost  hover paints the colour; press and engaged mix 10% of the text
 *          colour into it, which deepens it in light mode and lifts it in dark
 *   tag    the face is the colour at --surface-tag-alpha, unless the palette
 *          sets a per-colour strength (--tag-yellow-alpha)
 *
 * Theme tokens (:root and .dark) hold colours only:
 *   --surface-{role}             face colours (canvas, panel, control, ...)
 *   --surface-edge[-well]        neutral perimeter colours
 *   --surface-highlight[-strong] neutral catchlights (transparent in light)
 *   --surface-shadow[-strong]    drop shadow colours
 *   --surface-shadow-inset       recess colour
 *   --surface-tint-{state}       neutral hover and pressed overlays
 *   --surface-tint-selected      selection overlay for selected rows
 *   --surface-tag-alpha          translucent tag strength
 *
 * Element tokens are registered as non-inheriting properties, so a nested
 * surface never picks up its parent's face or state. Override one on an
 * element to restyle a single surface, for example [--surface-face:...].
 *   --surface-face         fill colour, also painted as an opaque backing ring
 *   --surface-rim          1px perimeter
 *   --surface-catchlight   1px top-edge highlight above the perimeter
 *   --surface-backing      ring under the perimeter, so translucent rims are
 *                          not darkened by the drop shadow
 *   --surface-drop         three drop shadows (pad with transparent)
 *   --surface-recess       inset shadow for pressed and engaged states
 *   --surface-tint         state overlay painted over the face
 *   --surface-hover-tint   the tint hover paints (default --surface-tint-hover)
 *   --surface-press-tint   the tint press and engaged paint
 *
 * Every surface paints the same seven shadow layers in the same order, so
 * box-shadow transitions between states interpolate. The catchlight is
 * painted over the perimeter's top row, never as an inset line inside the
 * border. The recess starts inside the element's 1px transparent border.
 * The ink (#393a34) and light (#dedcd5) tints come from Vitesse.
 */

:root {
  --surface-light-source: oklch(100% 0 none);
  --surface-dark-source: oklch(0% 0 none);
  --surface-footer-mix: var(--surface-dark-source);
  --surface-canvas: oklch(97.613879% 0 none);
  --surface-panel: oklch(100% 0 none);
  --surface-control: oklch(100% 0 none);
  --surface-input: oklch(100% 0 none);
  --surface-overlay: oklch(100% 0 none);
  --surface-modal: oklch(100% 0 none);
  --surface-top: oklch(100% 0 none);
  --surface-well: oklch(34.541285% 0.01028535 114.61857deg / 5%);
  --surface-edge: oklch(34.541285% 0.01028535 114.61857deg / 10%);
  --surface-edge-well: oklch(34.541285% 0.01028535 114.61857deg / 8%);
  --surface-highlight: transparent;
  --surface-highlight-strong: transparent;
  --surface-highlight-divider: color-mix(in srgb, var(--surface-panel) 10%, transparent);
  --surface-catchlight-lift: 0%;
  --surface-shadow: oklch(34.541285% 0.01028535 114.61857deg / 6%);
  --surface-shadow-strong: oklch(34.541285% 0.01028535 114.61857deg / 10%);
  --surface-shadow-inset: oklch(34.541285% 0.01028535 114.61857deg / 10%);
  --surface-shadow-divider: color-mix(in srgb, var(--foreground) 8%, transparent);
  --surface-tint-hover: oklch(34.541285% 0.01028535 114.61857deg / 4%);
  --surface-tint-pressed: oklch(34.541285% 0.01028535 114.61857deg / 7%);
  --surface-tint-selected: color-mix(in srgb, var(--selection) 10%, transparent);
  --surface-tag-alpha: 10%;

  /* Fixed on long rules so wide separators do not lose their ends. */
  --separator-inset: min(8%, 1.5rem);
  --separator-fade: var(--separator-inset);
}

.dark {
  --surface-footer-mix: var(--surface-light-source);
  --surface-canvas: oklch(18.22037% 0 none);
  --surface-panel: oklch(20.903609% 0 none);
  --surface-control: oklch(23.503113% 0 none);
  --surface-input: color-mix(in srgb, var(--surface-control) 97.5%, var(--surface-light-source));
  --surface-overlay: oklch(25.196475% 0 none);
  --surface-modal: oklch(26.861828% 0 none);
  --surface-top: oklch(28.908005% 0 none);
  --surface-well: oklch(0% 0 none / 25%);
  --surface-edge: oklch(89.409654% 0.00970052 93.578683deg / 3%);
  --surface-edge-well: oklch(89.409654% 0.00970052 93.578683deg / 4%);
  --surface-highlight: oklch(89.409654% 0.00970052 93.578683deg / 6%);
  --surface-highlight-strong: oklch(89.409654% 0.00970052 93.578683deg / 9%);
  --surface-highlight-divider: var(--surface-highlight);
  --surface-catchlight-lift: 100%;
  --surface-shadow: oklch(0% 0 none / 30%);
  --surface-shadow-strong: oklch(0% 0 none / 50%);
  --surface-shadow-inset: oklch(0% 0 none / 35%);
  --surface-shadow-divider: var(--surface-shadow);
  --surface-tint-hover: oklch(89.409654% 0.00970052 93.578683deg / 2.5%);
  --surface-tint-pressed: oklch(0% 0 none / 12%);
  --surface-tint-selected: color-mix(in srgb, var(--selection) 10%, transparent);
  --surface-tag-alpha: 15%;
}

@theme inline {
  --color-surface-canvas: var(--surface-canvas);
  --color-surface-panel: var(--surface-panel);
  --color-surface-control: var(--surface-control);
  --color-surface-input: var(--surface-input);
  --color-surface-overlay: var(--surface-overlay);
  --color-surface-modal: var(--surface-modal);
  --color-surface-top: var(--surface-top);
  --color-surface-well: var(--surface-well);
}

/* Element tokens: non-inheriting, so their initial values are the defaults
   of every surface and nested surfaces start clean. */
@property --surface-face {
  inherits: false;
  initial-value: transparent;
  syntax: "*";
}

@property --surface-rim {
  inherits: false;
  initial-value: transparent;
  syntax: "*";
}

@property --surface-catchlight {
  inherits: false;
  initial-value: transparent;
  syntax: "*";
}

@property --surface-backing {
  inherits: false;
  initial-value: transparent;
  syntax: "*";
}

@property --surface-drop {
  inherits: false;
  initial-value:
    0 0 0 0 transparent,
    0 0 0 0 transparent,
    0 0 0 0 transparent;
  syntax: "*";
}

@property --surface-recess {
  inherits: false;
  initial-value: 0 0 0 0 transparent;
  syntax: "*";
}

@property --surface-seam {
  inherits: false;
  initial-value:
    0 0 0 0 transparent,
    0 0 0 0 transparent;
  syntax: "*";
}

@property --surface-tint {
  inherits: false;
  initial-value: transparent;
  syntax: "*";
}

@property --surface-hover-tint {
  inherits: false;
  initial-value: transparent;
  syntax: "*";
}

@property --surface-press-tint {
  inherits: false;
  initial-value: transparent;
  syntax: "*";
}

/* Elements that react to pointer hover and press. Composite-widget items
   (menuitem, option, treeitem) are highlighted by their widget and checked
   inputs (switch, checkbox, radio) by their checked state, so neither is here. */
@custom-variant surface-interactive {
  &:where(
    :any-link,
    button,
    summary,
    [role="button"],
    [role="combobox"],
    [role="tab"],
    input:is([type="button"], [type="submit"], [type="reset"])
  ) {
    @slot;
  }
}

/*
 * The base of every surface: one face, one seven-layer shadow, and the tint
 * overlay for hover and press. Without a role it is a flat interactive
 * surface (ghost and secondary controls); pair it with a bg-* colour.
 * State selectors use :where() so they win by order over the role's tokens
 * and lose to any utility a component adds. Defaults sit in :where(&), with
 * no specificity, so a role that builds on this one can replace them.
 */
@utility surface-flat {
  --surface-elevation:
    0 -1px 0 0 var(--surface-catchlight), 0 0 0 1px var(--surface-rim),
    0 0 0 1px var(--surface-backing), var(--surface-drop), inset var(--surface-recess),
    var(--surface-seam);

  border-color: transparent;
  background-color: var(--surface-face);
  background-image: linear-gradient(var(--surface-tint), var(--surface-tint));
  background-origin: border-box;

  @apply shadow-(--surface-elevation);

  :where(&) {
    --surface-hover-tint: var(--surface-tint-hover);
    --surface-press-tint: var(--surface-tint-pressed);
  }

  @media (hover: hover) {
    @variant surface-interactive {
      &:where(:hover):where(
          :not(:disabled, [data-disabled]:not([data-disabled="false"]), [aria-disabled="true"])
        ) {
        --surface-tint: var(--surface-hover-tint);
      }
    }
  }

  @variant engaged {
    &:where(:not(input, textarea)) {
      --surface-tint: var(--surface-press-tint);
    }
  }

  @variant surface-interactive {
    &:where(:active) {
      --surface-tint: var(--surface-press-tint);
    }
  }
}

/* A flat surface whose hover, press, and engaged states paint one colour:
   surface-ghost-error-soft. Press deepens the colour toward the text. */
@utility surface-ghost-* {
  --surface-hover-tint: --value(--color, [color]);
  --surface-press-tint: color-mix(in oklab, var(--surface-hover-tint), currentcolor 10%);

  @apply surface-flat;
}

/* Shared frame geometry. The shadow paints the rim in normal colour modes;
 * a system-colour border replaces it when forced colours remove shadows.
 * Keep this in the recipe so components need no border fallback classes. */
@utility surface-framed {
  @apply surface-flat;

  border-width: 0;

  @media (forced-colors: active) {
    border: 1px solid CanvasText;
  }
}

/* Neutral roles. Each one sets its face and elevation tokens, and runs the
   separators that divide it solid to its edges. */
@utility surface-panel {
  --surface-container-face: var(--surface-panel);
  --surface-face: var(--surface-panel);
  --surface-rim: var(--surface-edge);
  --surface-catchlight: var(--surface-highlight);
  --surface-backing: var(--surface-face);
  --surface-drop:
    0 1px 2px -1px var(--surface-shadow), 0 2px 6px -2px var(--surface-shadow), 0 0 0 0 transparent;

  @apply surface-framed;

  :where(&) {
    --separator-fade: 0%;
  }
}

/*
 * The raised, pressable surface. Fields and solid fills build on it, so its
 * depth, validity, and disabled states are written once. They come after the
 * flat states: pressed beats engaged and disabled beats both.
 */
@utility surface-control {
  @apply surface-flat;

  :where(&) {
    --separator-fade: 0%;
    --surface-face: var(--surface-control);
    --surface-rim: var(--surface-edge);
    --surface-catchlight: var(--surface-highlight);
    --surface-backing: var(--surface-face);
    --surface-drop:
      0 1px 1px -0.5px var(--surface-shadow-strong), 0 2px 4px -1px var(--surface-shadow),
      0 0 0 0 transparent;
  }

  @variant engaged {
    &:where(:not(input, textarea)) {
      --surface-catchlight: transparent;
      --surface-backing: transparent;
      --surface-drop: 0 0 0 0 transparent, 0 0 0 0 transparent, 0 0 0 0 transparent;
      --surface-recess: 0 1px 2px 0 var(--surface-shadow-inset);
    }
  }

  @variant surface-interactive {
    &:where(:active) {
      --surface-catchlight: transparent;
      --surface-backing: transparent;
      --surface-drop: 0 0 0 0 transparent, 0 0 0 0 transparent, 0 0 0 0 transparent;
      --surface-recess: 0 2px 3px -1px var(--surface-shadow-inset);
    }
  }

  &:where([aria-invalid="true"], :has(> :is(input, textarea)[aria-invalid="true"])) {
    --surface-rim: var(--error);
  }

  &:where(
    :disabled,
    [data-disabled]:not([data-disabled="false"]),
    [aria-disabled="true"],
    :has(> :is(input, textarea):disabled)
  ) {
    --surface-catchlight: transparent;
    --surface-backing: transparent;
    --surface-drop: 0 0 0 0 transparent, 0 0 0 0 transparent, 0 0 0 0 transparent;
    --surface-recess: 0 0 0 0 transparent;
  }
}

@utility surface-field {
  --surface-face: var(--surface-input);

  @apply surface-control;
}

@utility surface-overlay {
  --surface-face: var(--surface-overlay);
  --surface-rim: var(--surface-edge);
  --surface-catchlight: var(--surface-highlight-strong);
  --surface-backing: var(--surface-face);
  --surface-drop:
    0 2px 4px -1px var(--surface-shadow), 0 8px 16px -4px var(--surface-shadow),
    0 16px 32px -8px var(--surface-shadow-strong);

  @apply surface-framed;

  :where(&) {
    --separator-fade: 0%;
  }
}

@utility surface-modal {
  --surface-container-face: var(--surface-modal);
  --surface-face: var(--surface-modal);
  --surface-rim: var(--surface-edge);
  --surface-catchlight: var(--surface-highlight-strong);
  --surface-backing: var(--surface-face);
  --surface-drop:
    0 4px 8px -2px var(--surface-shadow), 0 16px 32px -8px var(--surface-shadow),
    0 32px 64px -16px var(--surface-shadow-strong);

  @apply surface-framed;

  :where(&) {
    --separator-fade: 0%;
  }
}

/* Attached sections inherit the container face, unlike non-inheriting --surface-face.
   Keep the fill opaque and the divider shared; elevation belongs to the container. */
@utility surface-footer {
  background-color: color-mix(
    in srgb,
    var(--surface-container-face, var(--surface-panel)) 96%,
    var(--surface-footer-mix)
  );

  @apply carve-top;
}

/* A hairline frame with no elevation, over a half-strength panel face. */
@utility surface-frame {
  --surface-face: color-mix(in srgb, var(--surface-panel) 50%, transparent);
  --surface-rim: var(--surface-edge);

  @apply surface-framed;

  :where(&) {
    --separator-fade: 0%;
  }
}

/* Paint the media edge above the pixels without taking up layout space. */
@utility image-hairline {
  :where(&) {
    position: relative;
    isolation: isolate;
  }

  &::after {
    position: absolute;
    z-index: 20;
    border-radius: var(--image-hairline-radius, inherit);
    box-shadow: inset 0 0 0 0.5px var(--image-hairline);
    content: "";
    inset: var(--image-hairline-inset, 0);
    pointer-events: none;
  }
}

/* Thumbs carry no backing ring, so any bg-* colour can replace the face. */
@utility surface-knob {
  --surface-face: var(--surface-control);
  --surface-rim: var(--surface-edge);
  --surface-catchlight: var(--surface-highlight-strong);
  --surface-drop:
    0 1px 2px 0 var(--surface-shadow-strong), 0 2px 4px -1px var(--surface-shadow),
    0 0 0 0 transparent;

  @apply surface-flat;
}

/* A recessed track: shaded from the top, no catchlight, no states. */
@utility surface-well {
  --surface-elevation:
    inset 0 1px 2px 0 var(--surface-shadow-inset), inset 0 0 0 1px var(--surface-edge-well);

  background-color: var(--surface-well);

  @apply shadow-(--surface-elevation);

  :where(&) {
    --separator-fade: 0%;
  }
}

/* Coloured roles. One colour input drives the face, rim, and catchlight.
   Solid fills prefer a contrast-adjusted fill token when the palette defines one. */
@utility surface-fill-* {
  --surface-face: --value(--color-fill-*, --color-*, [color]);
  --surface-rim: color-mix(in srgb, var(--surface-face) 88%, var(--surface-dark-source));
  --surface-catchlight: color-mix(in srgb, var(--surface-face) 80%, var(--surface-light-source));

  @apply surface-control;
}

@utility surface-tint-* {
  --surface-face: --value(--color, [color]);
  --surface-rim: color-mix(in oklab, currentcolor 10%, transparent);
  --surface-catchlight: color-mix(
    in srgb,
    color-mix(in srgb, var(--surface-face) 80%, var(--surface-light-source))
      var(--surface-catchlight-lift),
    color-mix(in oklab, currentcolor 5%, var(--surface-face))
  );
  --surface-backing: var(--surface-face);
  --surface-drop:
    0 1px 2px -1px var(--surface-shadow), 0 2px 6px -2px var(--surface-shadow), 0 0 0 0 transparent;

  @apply surface-flat;
}

/* Translucent tags: the face keeps its alpha and casts no backing ring.
   Names resolve against the tag palette first: surface-tag-red uses --tag-red.
   A palette colour can set its own strength: --tag-yellow-alpha. */
@utility surface-tag-* {
  --surface-tag-color: --value(--color-tag-*, --color-*, [color]);
  --surface-tag-strength: var(--surface-tag-alpha);
  --surface-tag-strength: --value(--tag-alpha-*);
  --surface-face: color-mix(
    in oklab,
    var(--surface-tag-color) var(--surface-tag-strength),
    transparent
  );
  --surface-rim: color-mix(in oklab, currentcolor 10%, transparent);
  --surface-catchlight: color-mix(
    in srgb,
    color-mix(in srgb, transparent 80%, var(--surface-light-source)) var(--surface-catchlight-lift),
    color-mix(in oklab, currentcolor 5%, transparent)
  );
  --surface-drop:
    0 1px 2px -1px var(--surface-shadow), 0 2px 6px -2px var(--surface-shadow), 0 0 0 0 transparent;

  @apply surface-flat;
}

/* One carved rule recipe for standalone separators and embedded dividers. */
@utility carve-rule {
  background-image: linear-gradient(
    var(--separator-direction, to bottom),
    var(--surface-shadow-divider) 0 1px,
    var(--surface-highlight-divider) 1px 2px
  );
}

@utility carve-top {
  @apply carve-rule;

  background-position: top;
  background-repeat: no-repeat;
  background-size: 100% 2px;
}

@utility carve-bottom {
  @apply carve-rule;

  background-position: bottom;
  background-repeat: no-repeat;
  background-size: 100% 2px;
}

@utility carve-start {
  --separator-direction: to right;

  @apply carve-rule;

  background-position: left;
  background-repeat: no-repeat;
  background-size: 2px 100%;

  &:dir(rtl) {
    background-position: right;
  }
}

/*
 * Separator ends. A rule either runs solid into the edges of the surface it
 * divides (full) or fades out before them (inset). --separator-fade is the
 * fade length at each end and inherits, so the nearest container decides:
 *   canvas                      inset: the page has no edge to meet
 *   surface-panel, -control,    full: structural dividers meet the rim
 *   -overlay, -modal, -frame,
 *   -well (and their @apply)
 *   separator-inset             inset again, for padded content in a surface
 * A separator's own variant, or a label, overrides its container. The two
 * utilities work on a separator or on any container of separators.
 */
@utility separator-full {
  --separator-fade: 0%;
}

@utility separator-inset {
  --separator-fade: var(--separator-inset);
}

/* A translucent shadow and catchlight follow the colour of their containing surface. */
[data-separator],
[data-slot="marker"][data-variant="separator"] {
  --separator-direction: to bottom;
  --separator-fade-direction: to right;
}

[data-separator]:not([data-labeled]),
[data-separator][data-labeled]::before,
[data-separator][data-labeled]::after,
[data-slot="marker"][data-variant="separator"]::before,
[data-slot="marker"][data-variant="separator"]::after {
  mask-image: linear-gradient(
    var(--separator-fade-direction),
    transparent,
    var(--foreground) var(--separator-fade),
    var(--foreground) calc(100% - var(--separator-fade)),
    transparent
  );
}

[data-separator][data-variant="inset"],
[data-slot="marker"][data-variant="separator"] {
  --separator-fade: var(--separator-inset);
}

[data-separator][data-variant="full"] {
  --separator-fade: 0%;
}

[data-separator][data-orientation="vertical"],
[data-slot="resizable-handle"][aria-orientation="vertical"] {
  --separator-direction: to right;
  --separator-fade-direction: to bottom;
}

[data-separator],
[data-separator][data-labeled]::before,
[data-separator][data-labeled]::after,
[data-slot="marker"][data-variant="separator"]::before,
[data-slot="marker"][data-variant="separator"]::after {
  @apply carve-rule;
}

[data-separator][data-labeled] {
  background-image: none;
}

[data-separator][data-labeled]::before,
[data-separator][data-labeled]::after,
[data-slot="marker"][data-variant="separator"]::before,
[data-slot="marker"][data-variant="separator"]::after {
  min-width: 0;
  height: 2px;
  flex: 1;
  content: "";
}

[data-separator][data-labeled][data-orientation="vertical"]::before,
[data-separator][data-labeled][data-orientation="vertical"]::after {
  width: 2px;
  height: auto;
  min-height: 0;
}

/* Every control in a group is a segment of one surface: the group owns the
   frame, and each segment keeps only its face, tint, and recess. Nested
   groups frame their own segments. Each segment after the first carries its
   seam as an inset --surface-seam shadow, so it works on <input> too. Explicit
   separators own their group's seams. */
@layer utilities {
  :is(
    [data-slot="button-group"],
    [data-slot="toggle-group"][data-variant="outline"][data-spacing="0"]
  ):has(> [data-slot]:not([data-slot="button-group"], [data-slot="button-group-separator"])) {
    @apply rounded-lg surface-control;

    & > [data-slot]:not([data-slot="button-group"], [data-slot="button-group-separator"]) {
      --surface-rim: transparent;
      --surface-catchlight: transparent;
      --surface-backing: transparent;
      --surface-drop: 0 0 0 0 transparent, 0 0 0 0 transparent, 0 0 0 0 transparent;

      border-width: 0;
      margin-block-start: 0;
      margin-inline-start: 0;

      &[aria-invalid="true"],
      &:has([aria-invalid="true"]) {
        outline: 1px solid var(--error);
      }

      /* Text carries no surface of its own, so it paints the seam directly. */
      &[data-slot="button-group-text"] {
        box-shadow: var(--surface-seam);
      }
    }

    &:not(:has(> [data-slot="button-group-separator"]))
      > [data-slot]:not([data-slot="button-group"], [data-slot="button-group-separator"])
      ~ [data-slot]:not([data-slot="button-group"], [data-slot="button-group-separator"]) {
      --surface-seam:
        inset 1px 0 0 0 var(--surface-shadow-divider),
        inset 2px 0 0 0 var(--surface-highlight-divider);

      &:dir(rtl) {
        --surface-seam:
          inset -1px 0 0 0 var(--surface-shadow-divider),
          inset -2px 0 0 0 var(--surface-highlight-divider);
      }
    }

    &[data-orientation="vertical"]:not(:has(> [data-slot="button-group-separator"]))
      > [data-slot]:not([data-slot="button-group"], [data-slot="button-group-separator"])
      ~ [data-slot]:not([data-slot="button-group"], [data-slot="button-group-separator"]) {
      --surface-seam:
        inset 0 1px 0 0 var(--surface-shadow-divider),
        inset 0 2px 0 0 var(--surface-highlight-divider);
    }
  }
}

