type ChartTextRole = "metadata" | "control";

// Chart legends require pixel numbers, not CSS lengths. Read the same tokens
// used by HTML; defaults also make definitions safe to construct during SSR.
export const chartTextRole = (role: ChartTextRole) => {
  const fallback =
    role === "metadata" ? { fontSize: 12, fontWeight: 400 } : { fontSize: 14, fontWeight: 500 };

  if (typeof document === "undefined") {
    return fallback;
  }

  const styles = getComputedStyle(document.documentElement);
  const scaleRole = role === "metadata" ? "control-sm" : "control";
  const size = styles.getPropertyValue(`--text-${scaleRole}`).trim();

  const weight =
    role === "metadata"
      ? 400
      : Number.parseFloat(styles.getPropertyValue("--text-control--font-weight"));

  const rootSize = Number.parseFloat(styles.fontSize);
  const value = Number.parseFloat(size);
  const pixels = size.endsWith("rem") ? value * rootSize : size.endsWith("px") ? value : Number.NaN;

  return {
    fontSize: Number.isFinite(pixels) ? pixels : fallback.fontSize,
    fontWeight: Number.isFinite(weight) ? weight : fallback.fontWeight,
  };
};

import * as React from "react";
import { createCopyToClipboard } from "@/registry/erbium/lib/copy-to-clipboard";
import type { CopyToClipboardOptions, CopyToClipboardValue } from "@/registry/erbium/lib/copy-to-clipboard";

/** React adapter for the shared clipboard lifecycle. */
export const useCopyToClipboard = (options: CopyToClipboardOptions = {}) => {
  const [clipboard] = React.useState(createCopyToClipboard);

  const state = React.useSyncExternalStore(
    clipboard.subscribe,
    clipboard.getSnapshot,
    clipboard.getServerSnapshot,
  );

  React.useEffect(
    () => () => {
      clipboard.dispose();
    },
    [clipboard],
  );

  const copyToClipboard = async (value: CopyToClipboardValue): Promise<boolean> =>
    await clipboard.copyToClipboard(value, options);

  return { ...state, copyToClipboard, reset: clipboard.reset };
};

export type { CopyToClipboardOptions, CopyToClipboardValue };

import { useEffect, useRef } from "react";
import type { MouseEvent, PointerEvent } from "react";

const INTERACTIVE =
  'a, button:not([data-slot="checkbox"]), input, select, textarea, [contenteditable]';

interface DragSelectOptions {
  /** Returns the index and selected state of the item under the pointer, or `null` when it is not selectable. */
  resolve: (target: Element, container: HTMLElement) => { index: number; selected: boolean } | null;
  /** Applies `selected` to every selectable item from `start` to `end`, inclusive. */
  selectRange: (start: number, end: number, selected: boolean, container: HTMLElement) => void;
}

/**
 * Press on an item and drag across its siblings to select or clear them in one gesture.
 * Spread the returned handlers on the element that contains the items.
 */
export const useDragSelect = ({ resolve, selectRange }: DragSelectOptions) => {
  const drag = useRef<{ index: number; selected: boolean } | null>(null);
  const suppressClick = useRef(false);
  const stopDrag = useRef<() => void>(null);

  useEffect(() => () => stopDrag.current?.(), []);

  return {
    onClickCapture(event: MouseEvent<HTMLElement>) {
      if (suppressClick.current) {
        suppressClick.current = false;
        event.preventDefault();
        event.stopPropagation();
      }
    },
    onPointerDown(event: PointerEvent<HTMLElement>) {
      const { target } = event;

      if (event.button !== 0 || event.pointerType === "touch" || !(target instanceof Element)) {
        return;
      }

      if (target.closest(INTERACTIVE)) {
        return;
      }

      const item = resolve(target, event.currentTarget);

      if (!item) {
        return;
      }

      stopDrag.current?.();
      suppressClick.current = false;
      drag.current = { index: item.index, selected: !item.selected };

      const preventTextSelection = (selectEvent: Event) => {
        selectEvent.preventDefault();
      };

      const stop = () => {
        drag.current = null;
        stopDrag.current = null;
        window.removeEventListener("pointerup", stop);
        window.removeEventListener("pointercancel", stop);
        window.removeEventListener("blur", stop);
        document.removeEventListener("selectstart", preventTextSelection);
        // The click that follows pointerup fires after this; release the guard once it has.
        window.setTimeout(() => {
          suppressClick.current = false;
        }, 0);
      };

      window.addEventListener("pointerup", stop);
      window.addEventListener("pointercancel", stop);
      window.addEventListener("blur", stop);
      document.addEventListener("selectstart", preventTextSelection);
      stopDrag.current = stop;
    },
    onPointerOver(event: PointerEvent<HTMLElement>) {
      const { current } = drag;

      if (!current || !(event.buttons & 1) || !(event.target instanceof Element)) {
        return;
      }

      const item = resolve(event.target, event.currentTarget);

      if (!item || item.index === current.index) {
        return;
      }

      // Let clicks that `selectRange` dispatches through.
      suppressClick.current = false;
      selectRange(
        Math.min(current.index, item.index),
        Math.max(current.index, item.index),
        current.selected,
        event.currentTarget,
      );
      current.index = item.index;
      // The drag already toggled the item it started on; swallow the click released over it.
      suppressClick.current = true;
    },
  };
};

import { useMediaQuery } from "@base-ui/react/unstable-use-media-query";

/** Below Tailwind's `md:`, the shadcn mobile breakpoint, so a viewport is never both mobile and `md`. */
const MOBILE_QUERY = "(width < 48rem)";

/**
 * Whether the viewport is mobile-sized. Built on Base UI's media query hook, so it follows
 * viewport changes through the `matchMedia` change event and never renders an unresolved value.
 * It is `false` on the server; pass `{ defaultMatches: true }` to change that, or
 * `{ noSsr: true }` in client-only apps to resolve on the first render.
 */
const useIsMobile = (options: useMediaQuery.Options = {}) => useMediaQuery(MOBILE_QUERY, options);

export { MOBILE_QUERY, useIsMobile };

